BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS companion_households (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','suspended')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS companion_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE,password_hash text NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','disabled')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS companion_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES companion_households(id),display_name text NOT NULL,age_band text NOT NULL CHECK(age_band IN('child','teen','adult','older_adult')),status text NOT NULL DEFAULT 'active' CHECK(status IN('active','deletion_pending','deleted')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS companion_memberships (tenant_id uuid NOT NULL REFERENCES companion_households(id),user_id uuid NOT NULL REFERENCES companion_users(id),profile_id uuid NOT NULL REFERENCES companion_profiles(id),role text NOT NULL CHECK(role IN('guardian','member','viewer')),status text NOT NULL DEFAULT 'active' CHECK(status IN('active','revoked')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,user_id,profile_id));
CREATE TABLE IF NOT EXISTS companion_preference_versions (id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES companion_households(id),profile_id uuid NOT NULL,sequence integer NOT NULL,parent_version_id uuid REFERENCES companion_preference_versions(id),preferences jsonb NOT NULL,accessibility jsonb NOT NULL,safety jsonb NOT NULL,spending_limit_minor bigint NOT NULL,locale text NOT NULL,age_band text NOT NULL,preference_digest text NOT NULL,created_by uuid NOT NULL REFERENCES companion_users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,profile_id) REFERENCES companion_profiles(tenant_id,id),UNIQUE(tenant_id,profile_id,sequence));
CREATE TABLE IF NOT EXISTS companion_connector_grants (id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES companion_households(id),profile_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('calendar','commerce','device','content','service')),provider text NOT NULL,scopes jsonb NOT NULL,consent_receipt text NOT NULL,expires_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN('active','revoked','expired','deletion_pending','deleted')),credential_reference text NOT NULL,created_by uuid NOT NULL REFERENCES companion_users(id),created_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz,FOREIGN KEY(tenant_id,profile_id) REFERENCES companion_profiles(tenant_id,id),UNIQUE(tenant_id,profile_id,kind,provider));
CREATE TABLE IF NOT EXISTS companion_connector_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES companion_households(id),profile_id uuid NOT NULL,grant_id uuid NOT NULL REFERENCES companion_connector_grants(id),source_event_id text NOT NULL,event_type text NOT NULL,payload_digest text NOT NULL,observed_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),UNIQUE(grant_id,source_event_id));
CREATE TABLE IF NOT EXISTS companion_recommendations (id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES companion_households(id),profile_id uuid NOT NULL,preference_version_id uuid NOT NULL REFERENCES companion_preference_versions(id),preference_digest text NOT NULL,recommendation_digest text NOT NULL,selected_option jsonb NOT NULL,alternatives jsonb NOT NULL,rejected jsonb NOT NULL,explanation jsonb NOT NULL,status text NOT NULL CHECK(status IN('proposed','saved','approved','queued','in_progress','completed','failed','dismissed','cancelled')),created_by uuid NOT NULL REFERENCES companion_users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,profile_id) REFERENCES companion_profiles(tenant_id,id),UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS companion_recommendation_feedback (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES companion_households(id),profile_id uuid NOT NULL,recommendation_id uuid NOT NULL REFERENCES companion_recommendations(id),rating integer CHECK(rating BETWEEN 1 AND 5),correction jsonb NOT NULL,created_by uuid NOT NULL REFERENCES companion_users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS companion_evaluations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES companion_households(id),evaluation_set_version text NOT NULL,policy_version text NOT NULL,passed boolean NOT NULL,failures jsonb NOT NULL,metrics jsonb NOT NULL,created_by uuid NOT NULL REFERENCES companion_users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS companion_service_subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES companion_households(id),profile_id uuid NOT NULL,provider text NOT NULL,account_reference text NOT NULL,service_snapshot jsonb NOT NULL,price_evidence_receipt text NOT NULL,terms_evidence_receipt text NOT NULL,evidence_observed_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN('active','cancellation_review','cancellation_queued','cancelled','retained')),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,profile_id) REFERENCES companion_profiles(tenant_id,id),UNIQUE(tenant_id,provider,account_reference));
CREATE TABLE IF NOT EXISTS companion_cancellation_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES companion_households(id),profile_id uuid NOT NULL,subscription_id uuid NOT NULL REFERENCES companion_service_subscriptions(id),assessment jsonb NOT NULL,eligible boolean NOT NULL,net_savings_minor bigint NOT NULL,evidence_digest text NOT NULL,created_by uuid NOT NULL REFERENCES companion_users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS companion_action_approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES companion_households(id),profile_id uuid NOT NULL,recommendation_id uuid NOT NULL REFERENCES companion_recommendations(id),actor_id uuid NOT NULL REFERENCES companion_users(id),role text NOT NULL,decision text NOT NULL CHECK(decision IN('approved','rejected')),recommendation_digest text NOT NULL,cost_minor_units bigint NOT NULL,rationale text NOT NULL,decided_at timestamptz NOT NULL DEFAULT now(),UNIQUE(recommendation_id,actor_id));
CREATE TABLE IF NOT EXISTS companion_provider_outbox (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES companion_households(id),profile_id uuid NOT NULL,grant_id uuid REFERENCES companion_connector_grants(id),capability text NOT NULL,aggregate_type text NOT NULL,aggregate_id uuid NOT NULL,command jsonb NOT NULL,payload_digest text NOT NULL,idempotency_key text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','claimed','delivered','retry','dead_letter','cancelled')),attempt_count integer NOT NULL DEFAULT 0 CHECK(attempt_count BETWEEN 0 AND 5),lease_token uuid,lease_expires_at timestamptz,next_attempt_at timestamptz,last_error_code text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,capability,idempotency_key));
CREATE TABLE IF NOT EXISTS companion_provider_receipts (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES companion_households(id),profile_id uuid NOT NULL,outbox_id bigint REFERENCES companion_provider_outbox(id),provider text NOT NULL,receipt_id text NOT NULL,remote_status text NOT NULL,payload_digest text NOT NULL,usage jsonb NOT NULL DEFAULT '{}'::jsonb,occurred_at timestamptz NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider,receipt_id));
CREATE TABLE IF NOT EXISTS companion_export_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES companion_households(id),profile_id uuid NOT NULL,status text NOT NULL CHECK(status IN('requested','building','ready','failed','expired')),artifact_reference text,artifact_digest text,expires_at timestamptz,requested_by uuid NOT NULL REFERENCES companion_users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS companion_deletion_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES companion_households(id),profile_id uuid NOT NULL,status text NOT NULL CHECK(status IN('requested','propagating','blocked_by_hold','ready_to_finalize','completed','failed')),legal_hold boolean NOT NULL DEFAULT false,requested_by uuid NOT NULL REFERENCES companion_users(id),created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE IF NOT EXISTS companion_deletion_propagations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES companion_households(id),profile_id uuid NOT NULL,deletion_request_id uuid NOT NULL REFERENCES companion_deletion_requests(id),grant_id uuid NOT NULL REFERENCES companion_connector_grants(id),status text NOT NULL CHECK(status IN('pending','sent','confirmed','failed','manual_required')),provider_receipt text,deadline_at timestamptz NOT NULL,last_error_code text,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(deletion_request_id,grant_id));
CREATE TABLE IF NOT EXISTS companion_audit_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES companion_households(id),profile_id uuid,actor_id uuid REFERENCES companion_users(id),action text NOT NULL,entity_type text NOT NULL,entity_id uuid NOT NULL,evidence jsonb NOT NULL DEFAULT '{}'::jsonb,occurred_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION companion_reject_evidence_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'companion evidence is append-only'; END $$;
DO $$ DECLARE table_name text; BEGIN
FOREACH table_name IN ARRAY ARRAY['companion_preference_versions','companion_connector_events','companion_recommendation_feedback','companion_evaluations','companion_cancellation_assessments','companion_action_approvals','companion_provider_receipts','companion_audit_events'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS immutable_evidence ON %I',table_name); EXECUTE format('CREATE TRIGGER immutable_evidence BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION companion_reject_evidence_mutation()',table_name); END LOOP;
FOREACH table_name IN ARRAY ARRAY['companion_profiles','companion_memberships','companion_preference_versions','companion_connector_grants','companion_connector_events','companion_recommendations','companion_recommendation_feedback','companion_evaluations','companion_service_subscriptions','companion_cancellation_assessments','companion_action_approvals','companion_provider_outbox','companion_provider_receipts','companion_export_requests','companion_deletion_requests','companion_deletion_propagations','companion_audit_events'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',table_name); EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %I',table_name); EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',table_name); END LOOP;
END $$;
COMMIT;
